const SUN_ENERGY := 1.0
const SKY_TOP := Color("6f6aa8")
const SKY_HORIZON := Color("f2a679")
const AMBIENT := Color("c9d3ff")
const AMBIENT_ENERGY := 0.95
const FOG_DENSITY := 0.006
const SAND := Color("cfa971")
const SAND_SALT := Color("ecdcc0")
const SAND_CLAY := Color("9a7a68")
const SAND_WET := Color("8f95a8")  # мокрый песок: холодный сдвиг в лиловый (art_style §1.5, тень уходит в синий)
const SAND_POOL := Color("5d9aa0")  # лужи отлива: выцветший бирюзовый
const POOL_EDGE := 0.34  # порог шума: мокрое пятно
const POOL_CORE := 0.52  # порог шума: лужа
const SAND_TEXELS := 240  # ~4 текс/м на поле 60 м: 1 тексель ≈ 25 см, песок крупным зерном (мелочь рисуют модели)

var cam: Camera3D
var nodes := {}


func _ready() -> void:
	_build_env()
	for k in SPOTS:
		nodes[k] = _place(k, SPOTS[k][0])
	if nodes.has("mage"):
		nodes["mage"].rotation_degrees.y = -20.0
	for k in CLIPS:
		var ap := nodes[k].find_child("AnimationPlayer", true, false) as AnimationPlayer
		if ap != null and ap.has_animation(CLIPS[k][0]):
			ap.play(CLIPS[k][0])
			ap.seek(CLIPS[k][1], true)
			ap.pause()
	pose("game", 0.0)


func pose(anim: String, t: float) -> void:
	if anim.begins_with("focus:"):
		var spot: Array = SPOTS[anim.substr(6)]
		var target: Vector3 = spot[0] + Vector3(0, spot[1], 0)
		cam.size = spot[2]
		cam.rotation_degrees = Vector3(CLOSE_PITCH_DEG, t, 0)
		cam.position = target + cam.basis.z * CAM_DIST
	else:
		cam.size = CAM_SIZE_GAME
		cam.rotation_degrees = Vector3(CAM_PITCH_DEG, 0, 0)
		cam.position = Vector3(-1.0, 3.6, 0.0) + cam.basis.z * CAM_DIST


func _place(model: String, pos: Vector3) -> Node3D:
	var n := (load(MODELS + model + ".glb") as PackedScene).instantiate() as Node3D
	add_child(n)
	n.position = pos
	return n


func _build_env() -> void:
	cam = Camera3D.new()
	cam.projection = Camera3D.PROJECTION_ORTHOGONAL
	cam.far = 200.0
	add_child(cam)
	var ground := MeshInstance3D.new()
	var box := BoxMesh.new()
	box.size = Vector3(60.0, 0.2, 60.0)
	ground.mesh = box
	var gm := StandardMaterial3D.new()
	gm.albedo_texture = _sand_texture()
	gm.texture_filter = BaseMaterial3D.TEXTURE_FILTER_NEAREST
	gm.uv1_scale = Vector3(1, 1, 1)
	gm.roughness = 1.0
	ground.material_override = gm
	ground.position = Vector3(0, -0.1, 0)
	add_child(ground)
	var sun := DirectionalLight3D.new()
	sun.rotation_degrees = Vector3(-42, -35, 0)
	sun.light_energy = SUN_ENERGY
	sun.light_color = SUN_COLOR
	sun.shadow_enabled = true
	add_child(sun)
	var sky_mat := ProceduralSkyMaterial.new()
	sky_mat.sky_top_color = SKY_TOP
	sky_mat.sky_horizon_color = SKY_HORIZON
	sky_mat.ground_horizon_color = SKY_HORIZON
	sky_mat.ground_bottom_color = SAND
	var sky := Sky.new()
	sky.sky_material = sky_mat
	var env := Environment.new()
	env.background_mode = Environment.BG_SKY
	env.sky = sky
	env.ambient_light_source = Environment.AMBIENT_SOURCE_COLOR
	env.ambient_light_color = AMBIENT
	env.ambient_light_energy = AMBIENT_ENERGY
	env.fog_enabled = true
	env.fog_light_color = SKY_HORIZON
	env.fog_density = FOG_DENSITY
	var we := WorldEnvironment.new()
	we.environment = env
	add_child(we)


## Песок: крупные тексели, три тона (охра / тёплая соль / глина) по двум октавам шума — без повторяющейся плитки.
func _sand_texture() -> ImageTexture:
	var n := FastNoiseLite.new()
	n.seed = 7
	n.frequency = 0.05
	var n2 := FastNoiseLite.new()
	n2.seed = 11
	n2.frequency = 0.21
	var n3 := FastNoiseLite.new()
	n3.seed = 23
	n3.frequency = 0.028
	var img := Image.create(SAND_TEXELS, SAND_TEXELS, false, Image.FORMAT_RGB8)
	for y in SAND_TEXELS:
		for x in SAND_TEXELS:
			var v := n.get_noise_2d(x, y) * 0.7 + n2.get_noise_2d(x, y) * 0.3
			var c := SAND.lerp(SAND_SALT if v > 0.0 else SAND_CLAY, clampf(absf(v) * 1.6, 0.0, 0.75))
			var w := n3.get_noise_2d(x, y)
			if w > POOL_EDGE:
				c = c.lerp(SAND_WET, clampf((w - POOL_EDGE) * 5.0, 0.0, 0.7))
			if w > POOL_CORE:
				c = c.lerp(SAND_POOL, clampf((w - POOL_CORE) * 6.0, 0.0, 0.8))
			img.set_pixel(x, y, c)
	return ImageTexture.create_from_image(img)

